type ActionRequest={title:string;description:string;confirmLabel?:string;danger?:boolean;inputLabel?:string;initialValue?:string;resolve:(value:boolean|string|null)=>void};
function askAction(options:Omit<ActionRequest,'resolve'>){return new Promise<boolean|string|null>(resolve=>window.dispatchEvent(new CustomEvent('catalysthub:action',{detail:{...options,resolve}})));}
type ToastItem = { id: string; kind: ToastKind; title: string; message: string; closing?: boolean };
function notifySuccess(message: string, title = 'Success') { showToast('success', message, title); }
function notifyError(message: string, title = 'Action could not be completed') { showToast('error', message, title); }

function ToastViewport() {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [action, setAction] = useState<ActionRequest | null>(null);
  const [input, setInput] = useState('');
  const busy = false;
  const timers = useRef(new Map<string, number>());
  const recent = useRef({ key: '', at: 0 });
  function dismissToast(id: string) {
    const timer = timers.current.get(id);
    if (timer) window.clearTimeout(timer);
    setToasts(items => items.map(item => item.id === id ? { ...item, closing: true } : item));
    timers.current.set(id, window.setTimeout(() => {
      setToasts(items => items.filter(item => item.id !== id));
      timers.current.delete(id);
    }, 180));
  }

  useEffect(() => {
    const show = (event: Event) => {
      const detail = (event as CustomEvent<{ kind?: ToastKind; title?: string; message?: string; duration?: number }>).detail;
      if (!detail?.message) return;
      const kind = detail.kind || 'success';
      const title = detail.title || ({ success: 'Success', error: 'Something went wrong', warning: 'Attention needed', info: 'Update' }[kind]);
      const key = `${kind}:${title}:${detail.message}`;
      if (recent.current.key === key && Date.now() - recent.current.at < 1200) return;
      recent.current = { key, at: Date.now() };
      const id = crypto.randomUUID();
      setToasts(items => [...items, { id, kind, title, message: detail.message! }].slice(-4));
      timers.current.set(id, window.setTimeout(() => dismissToast(id), Math.max(1800, detail.duration || 4200)));
    };
    const open = (event: Event) => {
      const detail = (event as CustomEvent<ActionRequest>).detail;
      setInput(detail.initialValue || '');
      setAction(detail);
    };
    window.addEventListener('catalysthub:toast', show);
    window.addEventListener('catalysthub:action', open);
    return () => {
      window.removeEventListener('catalysthub:toast', show);
      window.removeEventListener('catalysthub:action', open);
      timers.current.forEach(timer => window.clearTimeout(timer));
      timers.current.clear();
    };
  }, []);

  function finish(confirmed: boolean) {
    if (!action) return;
    action.resolve(action.inputLabel ? (confirmed ? input : null) : confirmed);
    setAction(null);
  }
  const iconByKind = { success: Check, error: CircleAlert, warning: TriangleAlert, info: Info };
  const styleByKind: Record<ToastKind, string> = {
    success: 'border-[#b9dfc7] text-[#205b3d] [&_.toast-icon]:bg-[#e7f5ec] [&_.toast-icon]:text-leaf',
    error: 'border-[#f0c5c0] text-[#8f3028] [&_.toast-icon]:bg-[#fff0ee] [&_.toast-icon]:text-[#a3443c]',
    warning: 'border-[#ecd9a8] text-[#765516] [&_.toast-icon]:bg-[#fff6dc] [&_.toast-icon]:text-[#9a6a17]',
    info: 'border-[#cbd8f0] text-[#355782] [&_.toast-icon]:bg-[#edf3ff] [&_.toast-icon]:text-[#5278b8]',
  };
  return <>{toasts.length > 0 && createPortal(<div aria-label="Notifications" className="fixed right-3 top-20 z-[120] flex w-[min(410px,calc(100vw-1.5rem))] flex-col gap-2.5 sm:right-6">
    {toasts.map(item => {
      const Icon = iconByKind[item.kind];
      return <div key={item.id} role={item.kind === 'error' ? 'alert' : 'status'} aria-live={item.kind === 'error' ? 'assertive' : 'polite'} className={`toast-card flex items-start gap-3 rounded-2xl border bg-white p-4 shadow-xl ${styleByKind[item.kind]} ${item.closing ? 'animate-toast-out' : 'animate-toast'}`}>
        <span className="toast-icon grid h-8 w-8 shrink-0 place-items-center rounded-full"><Icon size={17}/></span>
        <span className="min-w-0 flex-1"><span className="block text-xs font-extrabold">{item.title}</span><span className="mt-0.5 block text-xs leading-5 text-[#536159]">{item.message}</span></span>
        <button type="button" aria-label="Dismiss notification" onClick={() => dismissToast(item.id)} className="grid h-7 w-7 shrink-0 place-items-center rounded-lg text-muted transition hover:bg-canvas hover:text-ink"><X size={15}/></button>
      </div>;
    })}
  </div>, document.body)}{action&&createPortal(<div className="fixed inset-0 z-[150] grid min-h-dvh place-items-center overflow-y-auto bg-[#07130e]/70 p-4 backdrop-blur-[2px]" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)finish(false);}}><section role="alertdialog" aria-modal="true" aria-labelledby="action-title" aria-describedby="action-description" className="my-auto w-full max-w-md rounded-2xl border border-line bg-white p-6 shadow-2xl animate-modal"><div className={`mb-4 grid h-11 w-11 place-items-center rounded-xl ${action.danger?'bg-red-50 text-red-700':'bg-[#e7f5ec] text-leaf'}`}>{action.danger?<Trash2 size={19}/>:<ShieldCheck size={19}/>}</div><h2 id="action-title" className="text-lg font-extrabold">{action.title}</h2><p id="action-description" className="mt-2 text-sm leading-6 text-muted">{action.description}</p>{action.inputLabel&&<label className="mt-4 block text-xs font-semibold">{action.inputLabel}<textarea autoFocus rows={3} maxLength={500} className="field mt-2 resize-none !text-sm" value={input} onChange={event=>setInput(event.target.value)}/></label>}<div className="mt-6 flex justify-end gap-2"><button type="button" disabled={busy} onClick={()=>finish(false)} className="btn btn-subtle text-sm">Cancel</button><button type="button" disabled={busy} onClick={()=>finish(true)} className={`btn text-sm ${action.danger?'bg-[#a3443c] text-white hover:bg-[#8e3933]':'btn-primary'}`}>{action.confirmLabel||'Confirm'}</button></div></section></div>,document.body)}</>;
}
function SessionRestoreError() {
  const { sessionError, retrySession } = useAuth();
  return <div role="alert" className="mx-auto grid min-h-screen max-w-lg content-center justify-items-center px-6 text-center">
    <h1 className="text-lg font-extrabold">Could not connect to your workspace</h1>
    <p className="mt-2 text-sm leading-6 text-muted">{sessionError}</p>
    <button type="button" onClick={retrySession} className="btn btn-primary mt-5">Try again</button>
  </div>;
}
function Guard({ children }: { children: ReactNode }) { const { user, loading, sessionError } = useAuth(); if (loading) return <div className="grid min-h-screen place-items-center text-sm text-muted">Loading your workspace…</div>; if (sessionError) return <SessionRestoreError/>; return user ? <>{children}</> : <Navigate to="/login" replace/>; }
function Guest({ children }: { children: ReactNode }) { const { user } = useAuth(); return user ? <Navigate to="/" replace /> : <>{children}</>; }
export default function App() { return <><ToastViewport/><Routes><Route path="/" element={<RootEntry/>}/><Route path="/login" element={<Guest><AuthPage mode="login" /></Guest>} /><Route path="/register" element={<Guest><AuthPage mode="register" /></Guest>} /><Route path="/guest" element={<GuestPage/>}/><Route path="/*" element={<Guard><Shell /></Guard>} /></Routes></>; }

function RootEntry(){const {user,loading,sessionError}=useAuth();if(loading)return <div className="grid min-h-screen place-items-center text-sm text-muted">Loading CatalystHub…</div>;if(sessionError)return <SessionRestoreError/>;return user?<Shell/>:<LandingPage/>;}

