  return <section className="mb-5 rounded-2xl border border-[#d9e4da] bg-white p-5 shadow-card"><div className="flex items-center justify-between"><div><div className="text-[10px] font-extrabold tracking-[.15em] text-leaf">TEAM ACCESS</div><h2 className="mt-1 text-base font-extrabold">Agent approvals {agents.length>0&&<span className="ml-1 rounded-full bg-[#fff1db] px-2 py-1 text-xs text-[#905c17]">{agents.length}</span>}</h2><p className="mt-1 text-xs text-muted">Review agency agent signups before they can access requests.</p></div><ShieldCheck className="text-leaf" size={20}/></div>{error&&<p role="alert" className="mt-3 text-xs text-red-700">{error}</p>}<div className="mt-3 divide-y divide-line">{agents.map(agent=><div key={agent.id} className="flex flex-wrap items-center gap-3 py-3"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><Link to={`/profile/${agent.id}`} className="text-sm font-bold hover:text-leaf hover:underline">{agent.name}</Link><RoleBadge role="agent"/></div><div className="text-xs text-muted">{agent.email} · requested {new Date(agent.createdAt).toLocaleDateString()}</div></div><button disabled={!!pendingId} onClick={()=>void decide(agent.id,'rejected')} className="btn btn-subtle !px-3 !py-2 text-xs">{pendingId===agent.id?'Saving…':'Reject'}</button><button disabled={!!pendingId} onClick={()=>void decide(agent.id,'approved')} className="btn btn-primary !px-3 !py-2 text-xs"><Check size={14}/>{pendingId===agent.id?'Saving…':'Approve'}</button></div>)}</div></section>;
